WITH flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), sessions_device_readings AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT device_code, CASE WHEN pressure >= 1032 THEN 'HIGH' ELSE 'LOW' END AS pressure_tier, BIT_AND(status_bits) AS status_bits_bit_and, SIZE(COLLECT_SET(device_code)) AS num_device_codes, (UNIX_TIMESTAMP(MAX(reading_ts)) - UNIX_TIMESTAMP(MIN(reading_ts))) / 60 AS duration_min, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list FROM sessions_device_readings GROUP BY device_code, CASE WHEN pressure >= 1032 THEN 'HIGH' ELSE 'LOW' END ORDER BY duration_min NULLS LAST
